j:jelly.script:
var params = new URLSearchParams(window.location.search);
var highlightData = params.get('sysparam_citation');
if(highlightData){
	addLoadEvent(function() {
			setTimeout(function() {

					var value = JSON.parse(highlightData);
					var hash = "#:~:text=";
					if(value.prefix){
						var prefix = encodeURIComponent(value.prefix);
						prefix = prefix.replace(/-/g, '%2D');
						hash = hash + prefix + "-" + ",";
					}
					if(value.start){
						var start = encodeURIComponent(value.start);
						start = start.replace(/-/g, '%2D');
						hash = hash + start;
					}
					if(value.end){
						var end = encodeURIComponent(value.end);
						end = end.replace(/-/g, '%2D');
						hash = hash + "," + end;
					}
					if(value.suffix){
						var suffix = encodeURIComponent(value.suffix);
						suffix = suffix.replace(/-/g, '%2D');
						hash = hash + "," + "-" + suffix;
					}

					window.location.hash = hash;
					const url = new URL(window.location.href);
					url.searchParams.delete('sysparam_citation');
					history.replaceState(null, '', url.toString());
			}, 1500);
		});
}
